mapper.select:
SELECT bdi.billDetailId, bdi.itemId, bdi.itemNum, bdi.itemName, bdi.itemType, bdi.categoryId, bdi.categoryName, bdi.billNum, DATE_FORMAT( bdi.orderDate, '%Y-%m-%d' ), bdi.patientId, bdi.patientName, bdi.mobile, bdi.gender, bdi.executorId, bdi.executorName, bdi.price, bdi.quantity, bdi.totalOriginalAmount, bdi.discountAmount, bdi.totalOriginalAmount - bdi.discountAmount AS actualAmount FROM ( SELECT bbd.org_id AS orgId, bp.billId, bbd.bill_detail_id AS billDetailId, bbd.item_id AS itemId, bti.item_num AS itemNum, bti.item_name AS itemName, bbd.item_type AS itemType, bti.category_id AS categoryId, bti.category_name AS categoryName, bp.billNum, bp.orderDate, bp.patientId, bp.patientName, bp.pinyinName, bp.mobile, bp.gender, bbd.executor_id AS executorId, be.employee_name AS executorName, bbd.price, bbd.quantity, bbd.price * bbd.quantity AS totalOriginalAmount, bbd.discount_amount AS discountAmount FROM base_bill_detail bbd LEFT JOIN base_tariff_info bti ON bbd.item_id = bti.item_id AND bti.item_type = bti.item_type LEFT JOIN ( SELECT bb.bill_id AS billId, bb.order_date AS orderDate, bb.patient_id AS patientId, bb.bill_num AS billNum, bp.`name` AS patientName, bp.gender AS gender, bp.mobile AS mobile, bp.pinyin_name AS pinyinName FROM base_bill bb LEFT JOIN base_patient bp ON bb.patient_id = bp.patient_id ) bp ON bbd.bill_id = bp.billId LEFT JOIN base_employee be ON bbd.executor_id = be.user_id ) bdi
AND bdi.orgId = #{query.orgId}
AND DATE_FORMAT( bdi.orderDate, '%Y-%m' ) = #{query.orderDate}
AND concat(ifnull(bdi.patientName, ''), ifnull(bdi.pinyinName, ''), ifnull(bdi.mobile, '')) Like concat('%', #{query.keyWord}, '%')
ORDER BY bdi.orderDate DESC, bdi.billId, bdi.billDetailId
